  @VisibleForTesting
  public SlowDiskTracker getSlowDiskTracker() {
    return slowDiskTracker;
  }

  @VisibleForTesting
  public void addSlowPeers(String dnUuid) {
    slowNodesUuidSet.add(dnUuid);
  }

